import functools
def _pf_distinct_by(f, xs):
    seen = set()
    out = []
    for x in xs:
        k = f(x)
        if not k in seen:
            seen.add(k)
            out.append(x)
    return out
def _pf_filter(f, xs):
    return list(filter(f, xs))
def _pf_is_empty(xs):
    return len(xs) == 0
def _pf_list_contains(x, xs):
    return x in xs
def _pf_map(f, xs):
    return list(map(f, xs))
def _pf_map_contains(k, m):
    return k in m
def _pf_set_contains(x, s):
    return x in s
def _pf_str_ends_with(suf, s):
    return s.endswith(suf)
def _pf_str_starts_with(pre, s):
    return s.startswith(pre)
empties = _pf_filter(_pf_is_empty, [[1], [], [2, 3], []])
hasOne = _pf_map(functools.partial(_pf_list_contains, 1), [[1], [2]])
byMod = _pf_distinct_by(lambda x: x % 3, [1, 2, 3, 4, 5, 6, 7])
inSets = _pf_map(functools.partial(_pf_set_contains, 1), [set([1, 2]), set()])
inMaps = _pf_map(functools.partial(_pf_map_contains, 1), [dict([(1, "a")]), dict()])
aWords = _pf_filter(functools.partial(_pf_str_starts_with, "a"), ["ab", "ba", "aa"])
endA = _pf_filter(functools.partial(_pf_str_ends_with, "a"), ["ab", "ba", "aa"])
